import React from 'react';
import { Phone, Mail } from 'lucide-react';

const ContactInfo = ({ phone, email }) => {
  return (
    <div className="hidden lg:flex items-center space-x-6">
      <div className="text-right">
        <a 
          href="tel:+919825814883"
          className="flex items-center justify-end text-white text-sm mb-1 hover:text-[#5dade2] transition-colors"
        >
          <Phone className="w-4 h-4 mr-2" />
          {phone}
        </a>
        <a 
          href="mailto:info@krupanidhiropes.com"
          className="flex items-center justify-end text-gray-300 text-xs hover:text-[#5dade2] transition-colors"
        >
          <Mail className="w-3 h-3 mr-2" />
          {email}
        </a>
      </div>
      <a
        href="tel:+919825814883"
        className="border-2 border-white text-white hover:bg-white hover:text-[#3d3d3d] transition-all px-4 py-2 rounded text-sm font-medium"
      >
        CONNECT WITH US
      </a>
    </div>
  );
};

export default ContactInfo;
